const fs=require('fs');
const path=require('path');
const root=process.argv[2];
if(!root) throw new Error('usage: node patch-uep-08204-bundle.js <app-root>');
const must=(ok,msg)=>{if(!ok)throw new Error(msg)};
const gPath=path.join(root,'resources','app','gyomuon.js');
const cssPath=path.join(root,'resources','app','gyomuon.css');
const dataPath=path.join(root,'resources','app','electron','google-data.cjs');
const mainPath=path.join(root,'resources','app','electron','main.cjs');
let g=fs.readFileSync(gPath,'utf8'),css=fs.readFileSync(cssPath,'utf8'),data=fs.readFileSync(dataPath,'utf8'),main=fs.readFileSync(mainPath,'utf8');

must(g.includes('const APP_VERSION = "0.82.03";'),'APP_VERSION 0.82.03 marker missing');
g=g.replace('const APP_VERSION = "0.82.03";','const APP_VERSION = "0.82.04";');

const currentDormRe=/String\(row\["현재여부"\] \|\| ""\)\.trim\(\) === "Y" \|\|\s*String\(row\["학사상태"\] \|\| ""\)\.trim\(\) === "재사"/;
must(currentDormRe.test(data),'currentDorm OR rule marker missing');
data=data.replace(currentDormRe,'String(row["현재여부"] || "").trim() === "Y" &&\n          String(row["학사상태"] || "").trim() === "재사"');
const pastDormRe=/!\(String\(row\["현재여부"\] \|\| ""\)\.trim\(\) === "Y" \|\| String\(row\["학사상태"\] \|\| ""\)\.trim\(\) === "재사"\)/;
must(pastDormRe.test(data),'pastDormStudents OR rule marker missing');
data=data.replace(pastDormRe,'!(String(row["현재여부"] || "").trim() === "Y" && String(row["학사상태"] || "").trim() === "재사")');

const dormCardRe=/function dormGrowthCard\(row,term\)\{[\s\S]*?\n\}\nfunction dormStudentBasicInfoMarkup/;
must(dormCardRe.test(g),'dormGrowthCard block missing');g=g.replace(dormCardRe,"function dormExitBadge08204(row){\n  const status=String(row?.status||'').trim();\n  const departed=/퇴사|종료/.test(status)||Boolean(row?.endDate&&status!=='재사');\n  if(!departed)return {departed:false,label:''};\n  const raw=String(row?.endDate||'').trim();\n  const m=raw.match(/(?:\\d{4}[-/.])?(\\d{1,2})[-/.](\\d{1,2})/);\n  return {departed:true,label:m?`퇴사 ${Number(m[1])}/${Number(m[2])}`:'퇴사'};\n}\nfunction dormGrowthCard(row,term){\n  const student=(readonlyCache?.students||[]).find(s=>String(s.id)===String(row.studentId)||String(s.studentNo)===String(row.studentNo));\n  if(!student)return '';\n  const base=admissionBase(student.id),internal=dormInternalTrend(student,term),mock=dormMockTrend(student,term),manage=dormManagementBadge(student),bundle=studentRecordBundle(student),exit=dormExitBadge08204(row);\n  const reports=(bundle.reports||[]).filter(x=>x.submitted!==false).length, programs=(bundle.programs||[]).length;\n  const internalValue=internal.length>1?`<b>${internal[internal.length-1].value.toFixed(2)}</b>`:'';\n  const mockValue=mock.length?`<b>${mock[mock.length-1].value.toFixed(2)}</b>`:'';\n  const badges=[exit.label?`<em class=\"dorm-exit-badge\">${escapeHtml(exit.label)}</em>`:'',manage.label?`<em>${escapeHtml(manage.label)}</em>`:''].filter(Boolean).join('');\n  return `<button class=\"dorm-growth-card${exit.departed?' is-departed':''}\" data-dorm-growth-student=\"${escapeHtml(student.id)}\"><header><div><small>${escapeHtml(student.studentNo||row.studentNo||'')} · ${escapeHtml(classNumberOf(student)||String(student.className||row.className||'').replace(/\\D/g,'')||'-')}반 ${escapeHtml(student.number||row.number||'')}번</small><h4>${escapeHtml(student.name||row.name||'')}</h4></div><span class=\"dorm-card-badges\">${badges}</span></header><div class=\"dorm-card-grade\"><span><small>내신 5 / 9</small><b>${base.avg5==null?'-':base.avg5.toFixed(2)} <i>/ ${base.actual9==null?'-':base.actual9.toFixed(2)}</i></b></span><span><small>대입 관리</small><b>${escapeHtml(dormAdmissionLine(student))}</b></span></div><div class=\"dorm-card-trends\"><div><small>${internal.length>1?'내신 추세':'내신 단건'}</small>${dormSparkline(internal)}${internalValue}</div><div><small>${mock.length>1?'모의 추세':'모의 현황'}</small>${dormSparkline(mock)}${mockValue}</div></div><div class=\"dorm-card-foot\"><span>프로그램 ${programs} · 보고서 ${reports}</span><strong>${escapeHtml(manage.reason)}</strong></div></button>`;\n}\nfunction dormStudentBasicInfoMarkup");
css+="\n/* UEP_08204_DORM_EXIT_BADGE */\n.dorm-growth-card.is-departed{opacity:.68;filter:saturate(.72);}\n.dorm-growth-card .dorm-card-badges{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end;}\n.dorm-growth-card .dorm-card-badges:empty{display:none;}\n.dorm-growth-card .dorm-exit-badge{background:#f4e6e3!important;color:#8b4038!important;border:1px solid #dfb8b1!important;font-weight:900!important;}\n";

const readOld="[`'${target}'!A1:X200`]",readNew="[`'${target}'!A1:X5000`]";
must(main.includes(readOld),'selected report read-range marker missing');main=main.replace(readOld,readNew);
const earlyOld="if(headerOk)return {ok:true,repaired:false};";
const earlyNew="if(headerOk){\n    try{return await repairSelectedReportTailGaps08204(token,current);}\n    catch(error){try{await queueSelectedReportRepair08204(token,error?.message||String(error));}catch{}throw error;}\n  }";
must(main.includes(earlyOld),'selected report header-only return marker missing');main=main.replace(earlyOld,earlyNew);
const insertMarker="// v0.80.45: 21_선택보고서_정규화의 헤더/원장이 깨졌을 때 건강한 구글폼 원본에서 1회 자동 복구합니다.";
must(main.includes(insertMarker),'selected report insertion marker missing');main=main.replace(insertMarker,"// UEP_08204_SELECTED_REPORT_INTEGRITY_START\nasync function queueSelectedReportRepair08204(token,reason=''){\n  const now=new Date().toISOString();\n  const id='RETRY-SR-'+Date.now();\n  await appendSheetValues(token,UEP_PROCESSING_SPREADSHEET_ID,\"'92_재처리대기'!A:K\",[[id,'03_선택활동보고서','선택보고서 자동정규화','원본-정규화 무결성',String(reason||'자동 복구 실패'),now,'0','','대기','','v0.82.04 자동감지']]);\n}\nasync function repairSelectedReportTailGaps08204(token,current=[]){\n  const body=current.slice(3);\n  const existingSourceRows=new Set();\n  const usedIds=new Set();let maxId=0,lastUsedRow=3;\n  body.forEach((r,index)=>{\n    if((r||[]).some(v=>String(v??'').trim()))lastUsedRow=index+4;\n    const id=String(r?.[0]||'').trim();\n    if(id){usedIds.add(id);const n=Number(id.match(/^SR-(\\d+)$/)?.[1]||0);if(n>maxId)maxId=n;}\n    if(String(r?.[17]||'').trim()==='GOOGLE_FORM'){const sr=String(r?.[15]||'').trim();if(/^\\d+$/.test(sr))existingSourceRows.add(Number(sr));}\n  });\n  const RESPONSE_SHEET_ID='1K-Me8Pm8T2d5fGHoqSPEAu4RXozETUQ-N5pZVxjs8Hw';\n  const [rawResult,studentResult,programResult]=await Promise.all([\n    readSheetBatch(token,RESPONSE_SHEET_ID,[\"'03_선택활동보고서'!A1:M5000\"]),\n    readSheetBatch(token,UEP_SPREADSHEET_ID,[\"'02_학생마스터'!A1:R1500\"]),\n    readSheetBatch(token,UEP_SPREADSHEET_ID,[\"'10_선택활동마스터'!A1:AL1500\"])\n  ]);\n  const raw=rawResult?.[0]?.values||[],students=studentResult?.[0]?.values||[],programs=programResult?.[0]?.values||[];\n  if(raw.length<2)return {ok:true,repaired:false,count:0};\n  const missing=[];\n  for(let ri=1;ri<raw.length;ri++){\n    const r=raw[ri]||[];if(!r.some(v=>String(v??'').trim()))continue;\n    const answers=Array.from({length:6},(_,i)=>String(r[6+i]||'').trim());\n    if(!answers.some(Boolean))continue;\n    const sourceRow=ri+1;if(!existingSourceRows.has(sourceRow))missing.push({ri,r,answers,sourceRow});\n  }\n  if(!missing.length)return {ok:true,repaired:false,count:0};\n  const sh=(students[2]||[]).map(v=>String(v||'').trim()),si=Object.fromEntries(sh.map((h,i)=>[h,i]));\n  const byNo=new Map(),byName=new Map();\n  students.slice(3).forEach(r=>{\n    const no=String(r?.[si['학번']]??'').replace(/\\.0$/,'').trim(),name=String(r?.[si['성명']]??'').trim();\n    if(!no&&!name)return;\n    const item={id:String(r?.[si['학생ID']]||''),no,name};\n    if(no)byNo.set(no,item);\n    if(name){const a=byName.get(name)||[];a.push(item);byName.set(name,a);}\n  });\n  const ph=(programs[2]||[]).map(v=>String(v||'').trim()),pi=Object.fromEntries(ph.map((h,i)=>[h,i]));\n  const byProgramName=new Map();\n  programs.slice(3).forEach(r=>{\n    const id=String(r?.[pi['프로그램ID']]||'').trim(),name=String(r?.[pi['프로그램명']]||'').trim();if(!id||!name)return;\n    const key=normalizeSelectedReportProgramName(name),a=byProgramName.get(key)||[];a.push({id,name,semester:String(r?.[pi['학기']]||'')});byProgramName.set(key,a);\n  });\n  const rawHeader=(raw[0]||[]).map(v=>String(v||'').trim()),sectionLabels=['참여내용','인상경험','진로연계','추가탐구','어려움해결','성장내용'];\n  const rows=[];\n  for(const item of missing){\n    const r=item.r;\n    let studentNo=String(r[1]??'').replace(/\\.0$/,'').trim(),name=String(r[2]||'').trim();\n    let student=byNo.get(studentNo);\n    if(!student&&name){const ms=byName.get(name)||[];if(ms.length===1){student=ms[0];studentNo=student.no;}}\n    const studentId=student?.id||'';\n    const schoolYear=String(r[3]??'2026').replace(/\\.0$/,'').trim()||'2026',semester=String(r[4]||'1학기').trim()||'1학기';\n    const rawProgram=String(r[5]||'').trim(),candidates=byProgramName.get(normalizeSelectedReportProgramName(rawProgram))||[],program=candidates.find(p=>p.semester===semester)||candidates[0]||null;\n    if(!program)throw new Error('선택보고서 프로그램 매칭 실패: '+rawProgram);\n    const content=item.answers.map((value,i)=>value?`[${sectionLabels[i]}]\\n${value}`:'').filter(Boolean).join('\\n\\n');\n    const originalPairs=item.answers.map((value,i)=>value?{label:rawHeader[6+i]||sectionLabels[i],value}:null).filter(Boolean);\n    const submittedAt=reportDateTimeText(r[0]),consent=String(r[12]||'').trim(),studentKey=studentId||studentNo;\n    let reportId;do{reportId=`SR-${String(++maxId).padStart(5,'0')}`;}while(usedIds.has(reportId));usedIds.add(reportId);\n    const programId=program.id,logicalKey=`${schoolYear}|${semester}|${studentKey}|${programId}`,contentHash=crypto.createHash('sha256').update([studentKey,programId,content].map(v=>String(v||'').trim()).join('\\n'),'utf8').digest('hex');\n    rows.push([reportId,'선택활동',studentId,studentNo,name,schoolYear,semester,programId,program.name,submittedAt,'Y',/동의/.test(consent)?'동의함':consent,content,JSON.stringify(originalPairs),'REPORT_TEXT_V2',String(item.sourceRow),studentId?'정상':'확인필요','GOOGLE_FORM','GF-AUTO-'+String(item.sourceRow),'',logicalKey,submittedAt,'정상',contentHash]);\n  }\n  const start=lastUsedRow+1,end=start+rows.length-1;\n  if(end>5000)throw new Error('선택보고서 정규화 저장 가능 행을 초과했습니다.');\n  await updateSheetValues(token,UEP_PROCESSING_SPREADSHEET_ID,`'21_선택보고서_정규화'!A${start}:X${end}`,rows);\n  console.log(`[UEP] 선택보고서 원본-정규화 누락 자동 복구: ${rows.length}건`);\n  return {ok:true,repaired:true,count:rows.length};\n}\n// UEP_08204_SELECTED_REPORT_INTEGRITY_END\n"+insertMarker);

g+="\n/* UEP_08204_RELEASE_NOTES_ONCE_START */\n(function(){\n  if(typeof window==='undefined'||window.__UEP08204ReleaseNotesInstalled)return;window.__UEP08204ReleaseNotesInstalled=true;\n  const V='0.82.04',KEY='uep.updateNotes.lastShownVersion';\n  function close(){document.getElementById('uepUpdateNotes08204')?.remove();try{localStorage.setItem(KEY,V);localStorage.setItem('uep.releaseNotes.seen',V)}catch{}}\n  function show(){try{if(String(APP_VERSION)!==V||localStorage.getItem(KEY)===V)return}catch{return}document.querySelectorAll('[id^=\"uepUpdateNotes\"]').forEach(x=>x.remove());const l=document.createElement('div');l.id='uepUpdateNotes08204';l.style.cssText='position:fixed;inset:0;z-index:2147483010;background:rgba(20,31,35,.38);display:flex;align-items:center;justify-content:center;padding:24px';l.innerHTML='<div style=\"width:min(700px,92vw);background:#fff;border-radius:22px;padding:24px;box-shadow:0 26px 70px rgba(0,0,0,.22)\"><h2>UEP 0.82.04 업데이트</h2><ul><li>학사생 학기 카드에 퇴사일 배지를 표시하고 현재 재사 판정은 현재여부 Y + 재사 상태를 모두 충족하도록 통일했습니다.</li><li>선택활동 구글폼 보고서와 정규화 원장의 원본행 누락을 자동 감지·복구합니다.</li><li>자동 복구 실패 시 데이터처리 92_재처리대기에 기록해 조용한 누락을 방지합니다.</li><li>대시보드 보고서는 공통·선택 정규화 원장을 계속 단일 기준으로 사용합니다.</li></ul><button type=\"button\" style=\"float:right;border:0;border-radius:12px;background:#167866;color:#fff;padding:10px 18px;font-weight:900;cursor:pointer\">확인</button><div style=\"clear:both\"></div></div>';document.body.appendChild(l);l.querySelector('button').onclick=close;}\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(show,900),{once:true});else setTimeout(show,900);\n})();\n/* UEP_08204_RELEASE_NOTES_ONCE_END */\n";
for(const p of [path.join(root,'resources','app','package.json'),path.join(root,'package.json')]){if(fs.existsSync(p)){try{const x=JSON.parse(fs.readFileSync(p,'utf8'));if(x.version==='0.82.03'){x.version='0.82.04';fs.writeFileSync(p,JSON.stringify(x,null,2)+'\n','utf8')}}catch{}}}
fs.writeFileSync(gPath,g,'utf8');fs.writeFileSync(cssPath,css,'utf8');fs.writeFileSync(dataPath,data,'utf8');fs.writeFileSync(mainPath,main,'utf8');
